package com.yeyamo_mobile.api.mission_reward_service.infrastructure.persistence;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;import com.yeyamo_mobile.api.mission_reward_service.domain.AdminDefinitionStatus;import jakarta.persistence.*;
@Entity@Table(name="reward_definitions")public class RewardDefinitionEntity{
 @Id private UUID id;@Column(nullable=false,unique=true,length=80)private String code;@Column(nullable=false,length=40)private String type;@Column(nullable=false,precision=19,scale=4)private BigDecimal value;@Column(name="xp_cost",nullable=false)private int xpCost;private Integer stock;@Column(length=3)private String currency;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AdminDefinitionStatus status;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;
 public static RewardDefinitionEntity create(String code,String type,BigDecimal value,int xpCost,Integer stock,String currency){RewardDefinitionEntity e=new RewardDefinitionEntity();e.id=UUID.randomUUID();e.code=required(code);e.apply(type,value,xpCost,stock,currency);e.status=AdminDefinitionStatus.DRAFT;e.createdAt=Instant.now();e.updatedAt=e.createdAt;return e;}public void update(String type,BigDecimal value,int xpCost,Integer stock,String currency){apply(type,value,xpCost,stock,currency);updatedAt=Instant.now();}private void apply(String type,BigDecimal value,int xpCost,Integer stock,String currency){if(value==null||value.signum()<0||xpCost<0||stock!=null&&stock<0)throw new IllegalArgumentException("Reward values cannot be negative");this.type=required(type);this.value=value;this.xpCost=xpCost;this.stock=stock;this.currency=currency==null?null:currency.toUpperCase(Locale.ROOT);}public void status(AdminDefinitionStatus value){status=Objects.requireNonNull(value);updatedAt=Instant.now();}private static String required(String value){if(value==null||value.isBlank())throw new IllegalArgumentException("Required value");return value.trim();}
 public UUID getId(){return id;}public String getCode(){return code;}public String getType(){return type;}public BigDecimal getValue(){return value;}public int getXpCost(){return xpCost;}public Integer getStock(){return stock;}public String getCurrency(){return currency;}public AdminDefinitionStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}
}
